#!/bin/bash
# Builds the light, publishable copy of the Claro Empresas Day deck: presentacion/ from empresas-day/.
#
# empresas-day/ is the local deck (full-resolution images, generated by
# customers/claro/claro-empresas-day/refs/_to_deck.py) and is gitignored.
# presentacion/ is what GitHub Pages serves. Rerun this after every deck rebuild.
#
# Lives OUTSIDE presentacion/ on purpose: it deletes and recreates that folder
# (the Brainbest build-web.sh deleted itself when it lived inside, 260803).
set -e
HERE="$(cd "$(dirname "$0")" && pwd)"
SRC="$HERE/empresas-day"
DST="$HERE/presentacion"

rm -rf "$DST"
mkdir -p "$DST/assets/diagrams"
cp "$SRC"/index.html "$SRC"/toc.html "$SRC"/impress.js "$DST"/
cp -R "$SRC"/assets/brand "$SRC"/assets/video "$SRC"/assets/fiba_labs_monogram.png "$DST"/assets/

# 128 colours: marker drawings with soft washes on white, so the smaller palette
# is invisible (checked side by side on the cover and El camino, 261112) and each
# image drops from ~700 KB to ~170 KB. Resolution is untouched: the deck zooms in.
for f in "$SRC"/assets/diagrams/*.png; do
  magick "$f" -strip -colors 128 -define png:compression-level=9 "$DST/assets/diagrams/$(basename "$f")"
done

printf '# Claro Empresas Day: published copy\n\nGenerated by `../build-web.sh` from `../empresas-day/` (local, gitignored). Never edit by hand.\nThe text comes from `~/OS/customers/claro/claro-empresas-day/261111_topics.md`.\n' > "$DST/README.md"

echo "WEB COPY READY"
du -sh "$SRC" "$DST"
echo "images: $(ls "$DST"/assets/diagrams/*.png | wc -l)"
